action.code:
if (open_list.empty()) {
    return nullptr;
}

auto min_it = open_list.begin();
for (auto it = open_list.begin(); it != open_list.end(); ++it) {
    if ((*it)->f < (*min_it)->f) {
        min_it = it;
    }
}

Node* result = *min_it;
open_list.erase(min_it);
return result;
// END_CODE

